import{d as u,C as t,o as m,c as h,j as n,a,E as i,a3 as s}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"系辞上传","description":"《易传》之总纲——讲易之体用、圣人设卦观象系辞、大衍之数与天地之数，是进入易学思想的第一个入口。","frontmatter":{"title":"系辞上传","description":"《易传》之总纲——讲易之体用、圣人设卦观象系辞、大衍之数与天地之数，是进入易学思想的第一个入口。","category":"guide","aliases":["系辞上传","系辞上","系辞","xi ci zhuan shang"],"source":["《周易·系辞上传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/xi-ci-zhuan-shang.md","filePath":"yijing/shi-yi/xi-ci-zhuan-shang.md","lastUpdated":1790587309000}'),y={name:"yijing/shi-yi/xi-ci-zhuan-shang.md"},w=u({...y,setup(b){const l=[{id:"duan-01",label:"一、天尊地卑",showLabel:!0,sentences:[["天尊地卑，",{text:"乾",glossary:"g01"},{text:"坤",glossary:"g02"},"定矣。"],,["卑高以陈，贵贱位矣。"],,["动静有常，刚柔断矣。"],,["方以类聚，物以群分，",{text:"吉凶",glossary:"g08"},"生矣。"],,["在天成",{text:"象",glossary:"g05"},"，在地成形，变化见矣。"],,["是故刚柔相摩，八卦相荡；"],,["鼓之以雷霆，润之以风雨；"],,["日月运行，一寒一暑。"],,["乾",{text:"道",glossary:"g20"},"成男，坤道成女。"],,],note:["天在上而尊，地在下而卑，乾坤的位置就此确定；高低陈列开来，贵贱也就有了分位；动与静各有常规，刚与柔便可判断；同类相聚、异类相分，吉凶就由此产生；在天成为象、在地成为形，变化就显现出来。所以刚柔相互摩擦、八卦相互激荡，用雷霆来鼓动、用风雨来滋润，日月运行、一寒一暑，乾道成男、坤道成女。"]},{id:"duan-02",label:"二、乾知大始",showLabel:!0,sentences:[["乾知大始，坤作成物。"],,["乾以",{text:"易",glossary:"g03"},"知，坤以",{text:"简",glossary:"g04"},"能；"],,["易则易知，简则易从；"],,["易知则有亲，易从则有功；"],,["有亲则可久，有功则可大；"],,["可久则贤人之德，可大则贤人之业。"],,["易简而天下之理得矣。"],,["天下之理得，而成位乎其中矣。"],,],note:["乾主管创始，坤负责成就万物。乾以「易」见其智，坤以「简」成其能：易就容易被理解，简就容易跟随；易被理解就有人亲近，易被跟随就有成效；有亲近便可长久，有成效便可宏大；长久是贤人的德，宏大是贤人的业。易与简，便得了天下的道理；得了天下的道理，就能在天地之中确立自己的位置。"]},{id:"duan-03",label:"三、设卦观象",showLabel:!0,sentences:[["圣人设卦观象，系辞焉而明",{text:"吉凶",glossary:"g08"},"，刚柔相推而生变化。"],,["是故",{text:"吉凶",glossary:"g08"},"者，失得之象也；"],,[{text:"悔吝",glossary:"g09"},"者，忧虞之象也；"],,["变化者，进退之象也；"],,["刚柔者，昼夜之象也。"],,["六",{text:"爻",glossary:"g06"},"之动，三极之道也。"],,["是故君子所居而安者，易之序也；"],,["所乐而玩者，爻之辞也。"],,["是故君子居则观其象而玩其辞，动则观其变而玩其占，是以自天祐之，吉无不利。"],,],note:["圣人设立卦、观察象，附上卦爻辞来说明吉凶，刚柔互相推移而产生变化。所以吉凶是失与得的象，悔吝是忧虞的象，变化是进退的象，刚柔是昼夜的象；六爻的变动，就是天地人三才之道。所以君子安处的，是《易》的秩序；所乐于玩味的，是爻的辞。君子静居就观其象、玩其辞，行动就观其变、玩其占，因此得天之助，吉而无不利。"]},{id:"duan-04",label:"四、彖爻吉凶",showLabel:!0,sentences:[[{text:"彖",glossary:"g07"},"者，言乎象者也；"],,["爻者，言乎变者也。"],,[{text:"吉凶",glossary:"g08"},"者，言乎其失得也；"],,[{text:"悔吝",glossary:"g09"},"者，言乎其小疵也。"],,[{text:"无咎",glossary:"g10"},"者，善补过者也。"],,["是故列贵贱者存乎位，齐小大者存乎卦，"],,["辩",{text:"吉凶",glossary:"g08"},"者存乎辞，忧",{text:"悔吝",glossary:"g09"},"者存乎介，震",{text:"无咎",glossary:"g10"},"者存乎悔。"],,["是故卦有小大，辞有险易；辞也者，各指其所之。"],,],note:["彖是说明卦象的，爻是说明变化的；吉凶说的是失与得，悔吝说的是小的瑕疵，无咎说的是善于补过。所以排列贵贱在于「位」，整齐大小在于「卦」；辨别吉凶在于辞，忧念悔吝在于细微，震动而致无咎在于能悔。因此卦有大小，辞有险易——辞，就是各自指向它所要去的地方。"]},{id:"duan-05",label:"五、易与天地准",showLabel:!0,sentences:[["易与天地准，故能",{text:"弥纶",glossary:"g11"},"天地之道。"],,["仰以观于天文，俯以察于地理，是故知幽明之故；"],,["原始反终，故知死生之说；"],,["精气为物，游魂为变，是故知鬼",{text:"神",glossary:"g22"},"之情状。"],,["与天地相似，故不违；"],,["知周乎万物，而道济天下，故不过；"],,["旁行而不流，乐天知命，故不忧；"],,["安土敦乎仁，故能爱。"],,["范围天地之化而不过，曲成万物而不遗，"],,["通乎昼夜之道而知，故神无方而易无体。"],,],note:["《易》与天地相准，所以能包容天地的道理。仰观天文、俯察地理，因此知道幽明之故；推原初始、反求终局，因此知道死生之说；精气聚成物、游魂散为变，因此知道鬼神的情状。与天地相似，所以不违背；智慧周遍万物而道济天下，所以无过；旁行而不流荡，乐天知命，所以无忧；安于所居、敦厚行仁，所以能爱。范围天地之化而无过差，曲成万物而无遗漏，通晓昼夜之道而有所知——所以神无方所，易无定体。"]},{id:"duan-06",label:"六、一阴一阳",showLabel:!0,sentences:[["一阴一阳之谓道，继之者善也，成之者性也。"],,["仁者见之谓之仁，知者见之谓之知，百姓日用而不知，故君子之道鲜矣。"],,["显诸仁，藏诸用，鼓万物而不与圣人同忧，盛德大业至矣哉！"],,["富有之谓大业，日新之谓盛德。"],,[{text:"生生",glossary:"g12"},"之谓易，成象之谓乾，效法之谓坤，"],,["极数知来之谓占，通变之谓事，阴阳不测之谓神。"],,],note:["一阴一阳就叫做道，继此而生的就是善，成就此道的就是性。仁者见它说是仁，智者见它说是智，百姓日用而不知——所以君子之道很少人懂得。它显发于仁，藏用于日常，鼓动万物却不与圣人同忧，盛德大业就到了极点。富有叫做大业，日新叫做盛德。生生不已叫做易，成象叫做乾，效法叫做坤，极数知来叫做占，通变叫做事，阴阳不可测度叫做神。"]},{id:"duan-07",label:"七、易广矣大矣",showLabel:!0,sentences:[["夫易广矣大矣，以言乎远则不御，以言乎迩则静而正，以言乎天地之间则备矣。"],,["夫乾，其静也专，其动也直，是以大生焉。"],,["夫坤，其静也翕，其动也辟，是以广生焉。"],,["广大配天地，变通配四时，"],,["阴阳之义配日月，易简之善配至德。"],,],note:["《易》真是广大啊：说到远则无所止御，说到近则静而端正，说到天地之间则无所不备。乾，静时专一，动时刚直，所以能大生；坤，静时闭合，动时开张，所以能广生。广大与天地相配，变通与四时相配，阴阳之义与日月相配，易简之善与至德相配。"]},{id:"duan-08",label:"八、崇德广业",showLabel:!0,sentences:[["子曰：“易，其至矣乎！"],,["夫易，圣人所以崇德而广业也。"],,["知崇礼卑，崇效天，卑法地。"],,["天地设位，而易行乎其中矣。"],,["成性",{text:"存存",glossary:"g27"},"，道义之门。”"],,],note:["孔子说：《易》大概到了极致吧！《易》是圣人用来崇尚德行、广大事业的。智要崇高，礼要谦卑——崇高效法天，谦卑效法地。天地设定了位置，《易》就行于其中。成就本性而存之又存，这就是道义的门户。"]},{id:"duan-09",label:"九、拟议成变化",showLabel:!0,sentences:[["圣人有以见天下之",{text:"赜",glossary:"g24"},"，而拟诸其形容，象其物宜，是故谓之象。"],,["圣人有以见天下之动，而观其会通，以行其典礼，系辞焉以断其",{text:"吉凶",glossary:"g08"},"，是故谓之爻。"],,["言天下之至赜而不可恶也。"],,["言天下之至动而不可乱也。"],,["拟之而后言，议之而后动，拟议以成其变化。"],,],note:["圣人因见天下事理的繁赜，便比拟它的形容、摹象它的物宜，所以叫做「象」；因见天下事物的变动，便观察它的会通、施行它的典礼，附上卦爻辞来断定吉凶，所以叫做「爻」。说天下最繁赜的事而不可厌，说天下最变动的事而不可乱——比拟而后言，商议而后动，比拟商议而成其变化。"]},{id:"duan-10",label:"十、鸣鹤在阴",showLabel:!0,sentences:[["“鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。”"],,],note:["《易》上说：「鹤在隐蔽处鸣叫，它的同类应声相和；我有美酒，愿与你共享。」"]},{id:"duan-11",label:"十一、出其言善",showLabel:!0,sentences:[["子曰：“君子居其室，出其言善，则千里之外应之，况其迩者乎？"],,["居其室，出其言不善，则千里之外违之，况其迩者乎？"],,["言出乎身，加乎民；行发乎迩，见乎远。"],,["言行，君子之枢机。"],,["枢机之发，荣辱之主也。"],,["言行，君子之所以动天地也，可不慎乎！”"],,],note:["孔子说：君子住在屋里，说出的话是善的，千里之外也会响应，何况近处？说出的话不善，千里之外也会违背，何况近处？言语出于自身，加于民众；行为发于近处，显现于远方。言行是君子的枢机——枢机一动，就是荣辱的主宰。言行是君子用来感动天地的，能不谨慎吗！"]},{id:"duan-12",label:"十二、同人先号咷",showLabel:!0,sentences:[["“同人：先号咷而后笑。”"],,["子曰：“君子之道，或出或处，或默或语。二人同心，其利断金。同心之言，其臭如兰。”"],,],note:["《易》上说：「同人卦：先号咷大哭而后欢笑。」孔子说：君子之道，或出而仕、或处而隐，或沉默、或言语——二人同心，其利可以断金；同心之言，其气味如兰。"]},{id:"duan-13",label:"十三、藉用白茅",showLabel:!0,sentences:[["“初六，藉用白茅，",{text:"无咎",glossary:"g10"},"。”"],,["子曰：“苟错诸地而可矣，藉之用茅，何咎之有？慎之至也。夫茅之为物薄，而用可重也。慎斯术也以往，其无所失矣。”"],,],note:["《易》上说：「初六，用白茅垫着祭器，无咎。」孔子说：即使直接放在地上也可以，再用白茅垫着，有什么过错？这是谨慎到了极点。白茅这东西虽薄，用处却可以很重；用这种谨慎去做事，就不会有什么过失了。"]},{id:"duan-14",label:"十四、劳谦君子有终",showLabel:!0,sentences:[["“劳谦，君子有终，吉。”"],,["子曰：“劳而不伐，有功而不德，厚之至也。语以其功下人者也。德言盛，礼言恭；谦也者，致恭以存其位者也。”"],,],note:["《易》上说：「有功劳而能谦，君子有好的结局，吉。」孔子说：劳而不自夸，有功而不自居，这是厚德之至。说的是把自己的功劳置于人下。德要说盛大，礼要说恭敬；谦，就是以恭敬来保住自己的位置。"]},{id:"duan-15",label:"十五、亢龙有悔",showLabel:!0,sentences:[["“亢龙有悔。”"],,["子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”"],,],note:["《易》上说：「亢龙有悔。」孔子说：尊贵而没有实位，居高而没有民众，贤人在下位而无人辅佐，所以一动便有悔恨。"]},{id:"duan-16",label:"十六、不出户庭",showLabel:!0,sentences:[["“不出户庭，",{text:"无咎",glossary:"g10"},"。”"],,["子曰：“乱之所生也，则言语以为阶。君不密则失臣，臣不密则失身，",{text:"几",glossary:"g23"},"事不密则害成。是以君子慎密而不出也。”"],,],note:["《易》上说：「不出户庭，无咎。」孔子说：祸乱产生，往往以言语为阶梯。君不密则失臣，臣不密则失身，机密之事不密则害成——所以君子谨慎缄密，不轻易说出去。"]},{id:"duan-17",label:"十七、其知盗乎",showLabel:!0,sentences:[["子曰：“作易者，其知盗乎？易曰‘负且乘，致寇至。’"],,["负也者，小人之事也。乘也者，君子之",{text:"器",glossary:"g21"},"也。"],,["小人而乘君子之器，盗思夺之矣。上慢下暴，盗思伐之矣。"],,["慢藏诲盗，冶容诲淫。"],,["易曰：‘负且乘，致寇至。’盗之招也。”"],,],note:["孔子说：作《易》的人大概知道盗贼之事吧？《易》上说「负且乘，致寇至」——背东西是小人的事，乘车是君子的器物；小人却坐上了君子的器物，盗贼就想夺它了。上慢下暴，盗贼就想攻伐了。藏得慢就是教人偷盗，打扮得太艳就是教人淫乱。《易》上说「负且乘，致寇至」，正是招致盗贼啊。"]},{id:"duan-18",label:"十八、大衍之数",showLabel:!0,sentences:[[{text:"大衍",glossary:"g13"},"之数五十，其用四十有九。"],,["分而为二以象两，",{text:"挂一",glossary:"g15"},"以象三，",{text:"揲",glossary:"g14"},"之以四以象四时，归奇于扐以象闰；"],,["五岁再闰，故再扐而后挂。"],,["天数五，地数五。"],,["五位相得而各有合，天数二十有五，地数三十，凡天地之数五十有五，此所以成变化而行鬼神也。"],,],note:["大衍之数五十，其中用的是四十九。分而为二以象两仪，挂一以象三才，四根一组地数以象四时，把余数归拢以象闰月；五年两次闰，所以再归拢而后挂。天数五，地数五，五位相配而各有合；天数二十五，地数三十，凡天地之数五十有五——这是用来成就变化、通行鬼神之事的。"]},{id:"duan-19",label:"十九、乾之策",showLabel:!0,sentences:[["乾之",{text:"策",glossary:"g16"},"二百一十有六，坤之策百四十有四，凡三百六十，当期之日。"],,["二篇之策，万有一千五百二十，当万物之数也。"],,["是故四营而成易，十有八变而成卦，八卦而小成。"],,["引而伸之，触类而长之，天下之能事毕矣。"],,["显道神德行，是故可与酬酢，可与祐神矣。"],,],note:["乾的策二百一十六，坤的策一百四十四，共三百六十，合于一年的日数；两篇的策一万一千五百二十，合于万物之数。所以四营而成《易》，十八变而成卦，八卦就小成；再引申触类而增长，天下的能事便尽于此。显明道理、神妙德行，因此可以与人应对酬答，可以受神的祐助。"]},{id:"duan-20",label:"二十、圣人之道四",showLabel:!0,sentences:[["子曰：“知变化之道者，其知神之所为乎。”"],,["易有圣人之道四焉：以言者尚其辞，以动者尚其变，以制器者尚其象，以卜筮者尚其占。"],,],note:["孔子说：知道变化之道的人，大概就知道神之所为吧。《易》有圣人运用它的四条道：用来言说的崇尚其辞，用来行动的崇尚其变，用来制器的崇尚其象，用来卜筮的崇尚其占。"]},{id:"duan-21",label:"二十一、受命如响",showLabel:!0,sentences:[["是以君子将有为也，将有行也，问焉而以言，其受命也如响。"],,["无有远近幽深，遂知来物。非天下之至精，其孰能与于此。"],,["参伍以变，错综其数。"],,],note:["所以君子将要有所作为、有所行动，先问于《易》而言，它接受询问如同回声一样。无论远近幽深，都能知道将来之事——不是天下至精的东西，谁能做到这样？参伍以变化，错综其数。"]},{id:"duan-22",label:"二十二、通其变",showLabel:!0,sentences:[["通其变，遂成天下之文；极其数，遂定天下之象。非天下之至变，其孰能与于此。"],,],note:["通其变，便成天下的文采；极其数，便定天下的象——不是天下至变的东西，谁能做到这样？"]},{id:"duan-23",label:"二十三、易无思也",showLabel:!0,sentences:[["易无思也，无为也，寂然不动，感而遂通天下之故。非天下之至神，其孰能与于此。"],,["夫易，圣人之所以极深而研几也。"],,["唯深也，故能通天下之志；唯几也，故能成天下之务；唯神也，故不疾而速，不行而至。"],,["子曰：“易有圣人之道四焉”者，此之谓也。"],,],note:["《易》无思无为，寂然不动，有感则通天下之故——不是天下至神的东西，谁能做到这样？《易》是圣人用以极深而研几的：唯其深，所以能通天下之志；唯其几，所以能成天下之务；唯其神，所以不疾而速、不行而至。孔子说「《易》有圣人之道四焉」，说的就是这个。"]},{id:"duan-24",label:"二十四、天一地二",showLabel:!0,sentences:[["天一，地二；天三，地四；天五，地六；天七，地八；天九，地十。"],,["子曰：“夫易何为者也？夫易开物成务，冒天下之道，如斯而已者也。”"],,],note:["天一、地二，天三、地四，天五、地六，天七、地八，天九、地十。孔子说：《易》是做什么的呢？《易》开物成务、覆盖天下之道，如此而已。"]},{id:"duan-25",label:"二十五、通天下之志",showLabel:!0,sentences:[["是故圣人以通天下之志，以定天下之业，以断天下之疑。"],,["是故蓍之德圆而神，卦之德方以知，六爻之义易以贡。"],,["圣人以此",{text:"洗心",glossary:"g25"},"，退藏于密，",{text:"吉凶",glossary:"g08"},"与民同患。"],,],note:["所以圣人用它来通天下之志、定天下之业、断天下之疑。所以蓍的德圆而神，卦的德方而知，六爻之义易而能告；圣人以此洗心，退藏于密处，与百姓同其吉凶患难。"]},{id:"duan-26",label:"二十六、神以知来",showLabel:!0,sentences:[["神以知来，知以藏往，其孰能与此哉！古之聪明睿知，神武而不杀者夫。"],,["是以明于天之道，而察于民之故，是兴神物以前民用。"],,["圣人以此斋戒，以神明其德夫。"],,],note:["神能知来，智能藏往，谁能做到这样？只有古时聪明睿知、神武而不嗜杀的人吧。因此明于天之道、察于民之故，于是兴起神物以供民用；圣人以此斋戒，来神明其德。"]},{id:"duan-27",label:"二十七、阖户谓之坤",showLabel:!0,sentences:[["是故阖户谓之坤，辟户谓之乾，一阖一辟谓之变，往来不穷谓之通，"],,["见乃谓之象，形乃谓之器，制而用之谓之法，利用出入，民咸用之谓之神。"],,],note:["所以关门叫做坤，开门叫做乾；一关一开叫做变，往来不穷叫做通；显现出来叫做象，有了形体叫做器，制作而使用叫做法，出入皆可利用、百姓都用它叫做神。"]},{id:"duan-28",label:"二十八、易有大极",showLabel:!0,sentences:[["是故易有",{text:"大极",glossary:"g17"},"，是生",{text:"两仪",glossary:"g18"},"。",{text:"两仪",glossary:"g18"},"生",{text:"四象",glossary:"g19"},"。",{text:"四象",glossary:"g19"},"生八卦。"],,["八卦定",{text:"吉凶",glossary:"g08"},"，",{text:"吉凶",glossary:"g08"},"生大业。"],,],note:["所以《易》有大极，由此生出两仪；两仪生四象，四象生八卦；八卦定吉凶，吉凶生大业。"]},{id:"duan-29",label:"二十九、法象莫大",showLabel:!0,sentences:[["是故法象莫大乎天地；变通莫大乎四时；"],,["县象著明莫大乎日月；崇高莫大乎富贵；"],,["备物致用，立成器以为天下利，莫大乎圣人探赜索隐，钩深致远，以定天下之",{text:"吉凶",glossary:"g08"},"，成天下之亹亹者，莫大乎蓍龟。"],,],note:["所以取法之象没有大过天地的，变通没有大过四时的，悬象著明没有大过日月的，崇高没有大过富贵的；备物致用、立成器以利天下没有大过圣人的，探究繁赜、索求隐微、钩深致远以定天下之吉凶、成天下勤勉之事的，没有大过蓍龟的。"]},{id:"duan-30",label:"三十、天生神物",showLabel:!0,sentences:[["是故天生神物，圣人则之；天地变化，圣人效之；"],,["天垂象，见",{text:"吉凶",glossary:"g08"},"，圣人象之；河出图，洛出书，圣人则之。"],,],note:["所以天生神物，圣人取法它；天地变化，圣人效法它；天垂象、见吉凶，圣人摹象它；河出图、洛出书，圣人取法它。"]},{id:"duan-31",label:"三十一、易有四象",showLabel:!0,sentences:[["易有",{text:"四象",glossary:"g19"},"，所以示也。系辞焉，所以告也；定之以",{text:"吉凶",glossary:"g08"},"，所以断也。"],,],note:["《易》有四象，是用来示人的；附上卦爻辞，是用来告知的；定之以吉凶，是用来决断的。"]},{id:"duan-32",label:"三十二、自天祐之",showLabel:!0,sentences:[["易曰：“自天祐之，吉无不利。”"],,["子曰：“祐者，助也。天之所助者，顺也；人之所助者，信也。履信思乎顺，又以尚贤也。是以‘自天祐之，吉无不利’也。”"],,],note:["《易》上说「自天祐之，吉无不利」——孔子说：祐就是助。天所助的是顺，人所助的是信；履信而思顺，又崇尚贤才，所以「自天祐之，吉无不利」。"]},{id:"duan-33",label:"三十三、书不尽言",showLabel:!0,sentences:[["子曰：“书不尽言，言不尽意。”然则圣人之意，其不可见乎？"],,["子曰：“圣人立象以尽意，设卦以尽情伪，系辞焉以尽其言。变而通之以尽利，鼓之舞之以尽神。”"],,],note:["孔子说：书不尽言，言不尽意。那么圣人的意思，就不可见了吗？孔子说：圣人立象以尽意，设卦以尽情伪，系辞以尽其言，变而通之以尽利，鼓之舞之以尽神。"]},{id:"duan-34",label:"三十四、易之缊",showLabel:!0,sentences:[["乾坤，其易之缊邪？乾坤成列，而易立乎其中矣。"],,["乾坤毁，则无以见易。易不可见，则乾坤或几乎息矣。"],,],note:["乾坤，是《易》的底蕴吧？乾坤成列，《易》就立于其中了。乾坤毁，就无从见《易》；《易》不可见，乾坤也就几乎止息了。"]},{id:"duan-35",label:"三十五、形上形下",showLabel:!0,sentences:[["是故形而上者谓之道，形而下者谓之器。"],,["化而裁之谓之变，推而行之谓之通，举而错之天下之民谓之事业。"],,],note:["所以形而上的叫做道，形而下的叫做器；化而裁之叫做变，推而行之叫做通，举而措之于天下之民叫做事业。"]},{id:"duan-36",label:"三十六、是故夫象",showLabel:!0,sentences:[["是故夫象，圣人有以见天下之赜，而拟诸其形容，象其物宜，是故谓之象。"],,],note:["所以所谓「象」，是圣人因见天下事理的繁赜，比拟它的形容、摹象它的物宜，所以叫做「象」。"]},{id:"duan-37",label:"三十七、是故谓之爻",showLabel:!0,sentences:[["圣人有以见天下之动，而观其会通，以行其典礼，系辞焉以断其",{text:"吉凶",glossary:"g08"},"，是故谓之爻。"],,],note:["圣人因见天下事物的变动，观察它的会通、施行它的典礼，附上卦爻辞来断定吉凶，所以叫做「爻」。"]},{id:"duan-38",label:"三十八、存乎德行",showLabel:!0,sentences:[["极天下之赜者存乎卦，鼓天下之动者存乎辞；"],,["化而裁之存乎变；推而行之存乎通；"],,["神而明之存乎其人；默而成之，不言而信，存乎德行。"],,],note:["极尽天下之繁赜在于卦，鼓动天下之动在于辞；化而裁之在于变，推而行之在于通；神而明之在于其人；默然而成之、不言而取信，在于德行。"]}],o=[{id:"g01",term:"乾",pinyin:"qián",meaning:"阳、天、创始之力。「乾知大始」——乾主导开始，是方向、是意志、是那个「第一动」；「成象之谓乾」，乾的功能是成就形象。"},{id:"g02",term:"坤",pinyin:"kūn",meaning:"阴、地、成物之力。「坤作成物」——坤负责完成与落地，把乾的方向变成具体的物；「效法之谓坤」，坤的功能是承接效法。"},{id:"g03",term:"易",pinyin:"yì",meaning:"三义并包：变易（阴阳往来）、简易（易则易知）、不易（常理）。“生生之谓易”——不断地生、生了又生，才是《易》最核心的定义。"},{id:"g04",term:"简",pinyin:"jiǎn",meaning:"简约、朴素。「坤以简能」——坤的方式是简，踏实、不花巧；执行最需要的是稳定与可重复。易与简之别：易是认知层面的透明，简是操作层面的可靠。"},{id:"g05",term:"象",pinyin:"xiàng",meaning:"圣人见天下之赜，拟诸其形容、象其物宜而立的象。「见乃谓之象」——可被看见、可被感知的征象。象是先于辞的，言说不尽处，由象来显意。"},{id:"g06",term:"爻",pinyin:"yáo",meaning:"「爻者，言乎变者也」——爻讲的是每一爻的变动与具体情境；「六爻之义易以贡」，六爻最具体地呈现时位与变化。"},{id:"g07",term:"彖",pinyin:"tuàn",meaning:"「彖者，言乎象者也」——彖辞说整卦的形象与整体义理，是静态的一卦之断。"},{id:"g08",term:"吉凶",pinyin:"jí xiōng",meaning:"「吉凶者，失得之象也」——吉凶是得失判断，不是道德好坏判断；「八卦定吉凶，吉凶生大业」，看清吉凶而适当行动，才有大业。"},{id:"g09",term:"悔吝",pinyin:"huǐ lìn",meaning:"「悔吝者，忧虞之象也」「言乎其小疵也」——小毛病、还未酿成大错的预警；「忧悔吝者存乎介」，要在细微的关键节点上警觉。"},{id:"g10",term:"无咎",pinyin:"wú jiù",meaning:"「无咎者，善补过者也」——不是「没有错」，而是有错但善于补救；「震无咎者存乎悔」——无咎来自主动的悔悟与震动。"},{id:"g11",term:"弥纶",pinyin:"mí lún",meaning:"弥是充满，纶是贯穿。「弥纶天地之道」——《易》充满并贯穿天地的一切道理，没有遗漏。"},{id:"g12",term:"生生",pinyin:"shēng shēng",meaning:"「生生之谓易」——不断地生、生了又生。变化可以是破坏性的，生生是创造性的；每一次变化都是新生命的诞生。"},{id:"g13",term:"大衍",pinyin:"dà yǎn",meaning:"大衍之数五十，其用四十有九。大衍是演算天地变化的数；五十为太极之体，不动不用；四十九为大衍之用，动而演化。"},{id:"g14",term:"揲",pinyin:"shé",meaning:"「揲之以四以象四时」——每四根蓍草一组地数，象春夏秋冬四时；是筮法「四营」之一。"},{id:"g15",term:"挂一",pinyin:"guà yī",meaning:"「挂一以象三」——从右堆取一根蓍草挂于指间，象天、地、人三才。"},{id:"g16",term:"策",pinyin:"cè",meaning:"蓍草之数。《乾》之策二百一十有六，《坤》之策百四十有四，合三百六十，当期之日；二篇之策万有一千五百二十，当万物之数。"},{id:"g17",term:"太极（大极）",pinyin:"tài jí",meaning:"「《易》有大极，是生两仪」——万有未分而含具一切变化的根源，不是物体，是变化的根。通行本多作「太极」。"},{id:"g18",term:"两仪",pinyin:"liǎng yí",meaning:"阴与阳。不是对立而是相待：无阖辟无所从出，无辟阖不能成用；两仪一发生，变化就有了最基本的动力。"},{id:"g19",term:"四象",pinyin:"sì xiàng",meaning:"阴阳消长的四种状态：少阳、老阳、少阴、老阴。四象说的不是两个静态标签，而是阴阳的时序与程度——盛不可恃，穷不可绝。"},{id:"g20",term:"道",pinyin:"dào",meaning:"「形而上者谓之道」——贯通万物的原理、秩序与方向；「一阴一阳之谓道」——道不是静止的，是阴阳之间那个永恒的来回。"},{id:"g21",term:"器",pinyin:"qì",meaning:"「形而下者谓之器」——已成形、可见、可操作的具体事物与方法制度。道必须通过器显现，器必须依道才不失正用。"},{id:"g22",term:"神",pinyin:"shén",meaning:"「阴阳不测之谓神」——神不是鬼神，是阴阳变化中那个不可完全测度的部分；「神无方」——神妙没有固定方位，无处不在。"},{id:"g23",term:"几",pinyin:"jī",meaning:"「极深而研几」——研究最细微、最初起、尚未完全显露的机兆。「唯几也，故能成天下之务」——在事机初起时把握关键。"},{id:"g24",term:"赜",pinyin:"zé",meaning:"「天下之赜」——幽深复杂、难以言说的复杂。「极天下之赜者存乎卦」——卦把最复杂的情状凝聚为可观之象。"},{id:"g25",term:"洗心",pinyin:"xǐ xīn",meaning:"「圣人以此洗心」——洗去私欲、成见、急于求答案的躁动；心能静、能诚、能不强求，象与辞才可能如其所是地显现。"},{id:"g26",term:"阖辟",pinyin:"hé bì",meaning:"「阖户谓之坤，辟户谓之乾」——关门收合象坤，开门开展象乾；一阖一辟谓之变，往来不穷谓之通。"},{id:"g27",term:"存存",pinyin:"cún cún",meaning:"「成性存存，道义之门」——成性不是一次就够，成了之后还要存，存了还要存；德是每天都要维护的状态。"}];return(p,e)=>{const r=t("DaoReadingPrelude"),g=t("DaoTextReading"),d=t("DaoKeywordCards");return m(),h("div",null,[e[0]||(e[0]=n("h1",{id:"系辞上传",tabindex:"-1"},[a("系辞上传 "),n("a",{class:"header-anchor",href:"#系辞上传","aria-label":'Permalink to "系辞上传"'},"​")],-1)),i(r,{title:"先通读全文，再顺着十七段的脉络读",summary:"《系辞上传》是十翼中最厚重的一篇，通论《易》之为书：从天尊地卑的宇宙生成，到易简之理、吉凶悔吝、大衍之数，再到一阴一阳之谓道与形上形下之分。全篇共十七段，层层推进，是进入易学思想的第一个入口。",points:[{label:"先读",text:"先把全文顺着读一遍，不逐字求解，抓大判断：易简、变通、生生、忧患。"},{label:"再辨",text:"留意天地、乾坤、圣人、君子、百姓——它们各自承担什么角色。"},{label:"后想",text:"最后回到具体章句（大衍之数、河洛之数）时，先知道它回答的是「筮法如何通于天」。"}],hint:"这篇虽长，内部结构很整：前段立宇宙论，中段论判断体系与君子之用，后段讲数与象，收束在德行。先读出整条脉络，再回到关键词与分段解读。"}),e[1]||(e[1]=s("",12)),i(g,{colophon:"天尊地卑 · 易简理得 · 一阴一阳 · 大衍之数",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"系辞上传原文",sections:l,glossary:o}),e[2]||(e[2]=n("blockquote",null,[n("p",null,"注：通行本多作「太极」，昇哥所用文本作「大极」，此处保留原文。下文「县象」之「县」通「悬」。")],-1)),e[3]||(e[3]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[a("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(d,{title:"字词释义",items:[{term:"乾",pinyin:["qián"],meaning:"阳、天、创始之力。「乾知大始」——乾主导开始，是方向、是意志、是那个「第一动」；「成象之谓乾」，乾的功能是成就形象。"},{term:"坤",pinyin:["kūn"],meaning:"阴、地、成物之力。「坤作成物」——坤负责完成与落地，把乾的方向变成具体的物；「效法之谓坤」，坤的功能是承接效法。"},{term:"易",pinyin:["yì"],meaning:"三义并包：变易（阴阳往来）、简易（易则易知）、不易（常理）。“生生之谓易”——不断地生、生了又生，才是《易》最核心的定义。"},{term:"简",pinyin:["jiǎn"],meaning:"简约、朴素。「坤以简能」——坤的方式是简，踏实、不花巧；执行最需要的是稳定与可重复。易与简之别：易是认知层面的透明，简是操作层面的可靠。"},{term:"象",pinyin:["xiàng"],meaning:"圣人见天下之赜，拟诸其形容、象其物宜而立的象。「见乃谓之象」——可被看见、可被感知的征象。象是先于辞的，言说不尽处，由象来显意。"},{term:"爻",pinyin:["yáo"],meaning:"「爻者，言乎变者也」——爻讲的是每一爻的变动与具体情境；「六爻之义易以贡」，六爻最具体地呈现时位与变化。"},{term:"彖",pinyin:["tuàn"],meaning:"「彖者，言乎象者也」——彖辞说整卦的形象与整体义理，是静态的一卦之断。"},{term:"吉凶",pinyin:["jí","xiōng"],meaning:"「吉凶者，失得之象也」——吉凶是得失判断，不是道德好坏判断；「八卦定吉凶，吉凶生大业」，看清吉凶而适当行动，才有大业。"},{term:"悔吝",pinyin:["huǐ","lìn"],meaning:"「悔吝者，忧虞之象也」「言乎其小疵也」——小毛病、还未酿成大错的预警；「忧悔吝者存乎介」，要在细微的关键节点上警觉。"},{term:"无咎",pinyin:["wú","jiù"],meaning:"「无咎者，善补过者也」——不是「没有错」，而是有错但善于补救；「震无咎者存乎悔」——无咎来自主动的悔悟与震动。"},{term:"弥纶",pinyin:["mí","lún"],meaning:"弥是充满，纶是贯穿。「弥纶天地之道」——《易》充满并贯穿天地的一切道理，没有遗漏。"},{term:"生生",pinyin:["shēng","shēng"],meaning:"「生生之谓易」——不断地生、生了又生。变化可以是破坏性的，生生是创造性的；每一次变化都是新生命的诞生。"},{term:"大衍",pinyin:["dà","yǎn"],meaning:"大衍之数五十，其用四十有九。大衍是演算天地变化的数；五十为太极之体，不动不用；四十九为大衍之用，动而演化。"},{term:"揲",pinyin:["shé"],meaning:"「揲之以四以象四时」——每四根蓍草一组地数，象春夏秋冬四时；是筮法「四营」之一。"},{term:"挂一",pinyin:["guà","yī"],meaning:"「挂一以象三」——从右堆取一根蓍草挂于指间，象天、地、人三才。"},{term:"策",pinyin:["cè"],meaning:"蓍草之数。《乾》之策二百一十有六，《坤》之策百四十有四，合三百六十，当期之日；二篇之策万有一千五百二十，当万物之数。"},{term:"太极（大极）",pinyin:["tài","jí"],meaning:"「《易》有大极，是生两仪」——万有未分而含具一切变化的根源，不是物体，是变化的根。通行本多作「太极」。"},{term:"两仪",pinyin:["liǎng","yí"],meaning:"阴与阳。不是对立而是相待：无阖辟无所从出，无辟阖不能成用；两仪一发生，变化就有了最基本的动力。"},{term:"四象",pinyin:["sì","xiàng"],meaning:"阴阳消长的四种状态：少阳、老阳、少阴、老阴。四象说的不是两个静态标签，而是阴阳的时序与程度——盛不可恃，穷不可绝。"},{term:"道",pinyin:["dào"],meaning:"「形而上者谓之道」——贯通万物的原理、秩序与方向；「一阴一阳之谓道」——道不是静止的，是阴阳之间那个永恒的来回。"},{term:"器",pinyin:["qì"],meaning:"「形而下者谓之器」——已成形、可见、可操作的具体事物与方法制度。道必须通过器显现，器必须依道才不失正用。"},{term:"神",pinyin:["shén"],meaning:"「阴阳不测之谓神」——神不是鬼神，是阴阳变化中那个不可完全测度的部分；「神无方」——神妙没有固定方位，无处不在。"},{term:"几",pinyin:["jī"],meaning:"「极深而研几」——研究最细微、最初起、尚未完全显露的机兆。「唯几也，故能成天下之务」——在事机初起时把握关键。"},{term:"赜",pinyin:["zé"],meaning:"「天下之赜」——幽深复杂、难以言说的复杂。「极天下之赜者存乎卦」——卦把最复杂的情状凝聚为可观之象。"},{term:"洗心",pinyin:["xǐ","xīn"],meaning:"「圣人以此洗心」——洗去私欲、成见、急于求答案的躁动；心能静、能诚、能不强求，象与辞才可能如其所是地显现。"},{term:"阖辟",pinyin:["hé","bì"],meaning:"「阖户谓之坤，辟户谓之乾」——关门收合象坤，开门开展象乾；一阖一辟谓之变，往来不穷谓之通。"},{term:"存存",pinyin:["cún","cún"],meaning:"「成性存存，道义之门」——成性不是一次就够，成了之后还要存，存了还要存；德是每天都要维护的状态。"}]}),e[4]||(e[4]=s("",27))])}}});export{x as __pageData,w as default};
